import {NoObjectGeneratedError} from 'ai';
import {test,expect,vi,afterEach} from 'vitest';
import {convexTest} from 'convex-test';
import {makeFunctionReference as ref} from 'convex/server';
import schema from '../convex/schema';
import {api,internal} from '../convex/_generated/api';
const generate=vi.hoisted(()=>vi.fn());vi.mock('@convex-dev/agent',()=>({Agent:class{generateText=generate;}}));
const modules=import.meta.glob('../convex/**/*.*s'),now=Date.parse('2026-10-11T04:30:00Z');
const q=(n:string)=>ref<'query',any,any>(n),m=(n:string)=>ref<'mutation',any,any>(n);
afterEach(()=>{vi.restoreAllMocks();vi.unstubAllEnvs();generate.mockReset();});
async function setup(){for(const [k,v] of Object.entries({INTUNE_PILOT_MODE:'v3',INTUNE_V4_ENABLED:'1',INTUNE_IMPLIED_SAVING:'1',INTUNE_DEBUG_LOGGING:'1',INTUNE_CONVERSATION_GATE:'candidate',PAYMENT_MODE:'razorpay_test',OPENAI_API_KEY:'synthetic',INTUNE_CONVERSATION_ROLLOUT:'all'}))vi.stubEnv(k,v);vi.spyOn(Date,'now').mockReturnValue(now);generate.mockImplementation(async(_c:any,_u:any,o:any)=>{const p=JSON.parse(o.prompt);return {text:JSON.stringify(p.task?.startsWith('Respond with')?{reply:p.proposal.reply}:{complete:true,missing:[]})};});const t=convexTest(schema,modules);const token=await t.mutation(internal.phoneUsers.getOrCreate,{phoneNumber:'+12025550198'});await t.run(async c=>{const u=await c.db.query('users').withIndex('by_token',x=>x.eq('token',token)).unique();await c.db.patch(u!._id,{pilotNameAsked:true});await c.db.insert('pilotEntitlements',{userId:u!._id,source:'operator_test',grantKey:'fictional-v4',eligibleAt:now,activationDeadline:now+604800000,startedAt:now,endsAt:now+604800000,welcomeState:'delivered',actor:'test'});});return {t,token,send:async(text:string,value:any,id=crypto.randomUUID(),quotedMessageId?:string)=>{generate.mockResolvedValueOnce({text:JSON.stringify(value)});return t.action(api.messages.send,{token,messageId:id,text,...(quotedMessageId?{quotedMessageId}:{})});}};}
test('V4 skips name, saves independent plans/experience, remembers context, and prevents duplicate AI calls (simulated AI)',async()=>{const {t,token,send}=await setup();const r=await send('I go to physio three times a week and get bloating',{introduced:true,reply:'Got it. Your physio plan and bloating are kept.',actions:[{type:'save',kind:'plan',label:'physio',targetNumber:3,evidence:'I go to physio three times a week'},{type:'save',kind:'experience',label:'bloating',evidence:'get bloating'}],tasks:[]},'mixed');expect(r.outcome).toBe('conversation');expect((await t.query(q('pilotMemory:overview'),{token})).items).toHaveLength(1);const context=await t.query(q('v4Store:context'),{token,messageId:'next',text:'what was my plan'});expect(context.state.records).toHaveLength(2);expect(context.history.some((h:any)=>h.text.includes('three times'))).toBe(true);const originalLog=await t.run(async ctx=>(await ctx.db.query('conversationLog').take(10)).find(r=>r.messageId==='mixed'&&r.direction==='incoming'));const count=generate.mock.calls.length;const duplicate=await t.action(api.messages.send,{token,messageId:'mixed',text:'I go to physio three times a week and get bloating'});expect(duplicate.outcome).toBe('provider_duplicate');expect(generate.mock.calls.length).toBe(count);const duplicateLog=await t.run(async ctx=>(await ctx.db.query('conversationLog').take(10)).find(r=>r.messageId==='mixed'&&r.direction==='incoming'));expect(duplicateLog).toEqual(originalLog);});
test('V4 malformed second action cannot partially save the first action (simulated AI)',async()=>{const {t,token,send}=await setup();generate.mockResolvedValueOnce({text:'invalid JSON'});const r=await send('I get bloating',{introduced:true,reply:'Saved.',actions:[{type:'save',kind:'experience',label:'bloating',evidence:'bloating'},{type:'save',kind:'experience',label:'invented',evidence:'invented'}],tasks:[]});expect(r.outcome).toBe('error');const c=await t.query(q('v4Store:context'),{token,messageId:'next',text:'show'});expect(c.state.records).toHaveLength(0);});
test('V4 corrections use owned IDs after expiry and quoted context, while new additions stay blocked (simulated AI)',async()=>{const {t,token,send}=await setup();await send('I need paneer',{introduced:true,reply:'Added paneer.',actions:[{type:'save',kind:'grocery',label:'paneer',evidence:'paneer',state:'pending'}],tasks:[]},'grocery');let c=await t.query(q('v4Store:context'),{token,messageId:'peek',text:'hi'});const id=c.state.records[0].id;vi.mocked(Date.now).mockReturnValue(now+604800000);const fixed=await send('I have paneer at home',{introduced:true,reply:'Paneer is marked as at home.',actions:[{type:'correct',targetId:id,evidence:'paneer at home',state:'held'}],tasks:[]},'correct','grocery');expect(fixed.outcome).toBe('conversation');c=await t.query(q('v4Store:context'),{token,messageId:'peek2',text:'hi',quotedMessageId:'grocery'});expect(c.state.records[0].state).toBe('held');expect(c.quoted.text).toBe('I need paneer');});
test('V4 delete clears conversational state, mapping copies and owned records (simulated AI)',async()=>{const {t,token,send}=await setup();await send('I need paneer',{introduced:true,reply:'Added paneer.',actions:[{type:'save',kind:'grocery',label:'paneer',evidence:'paneer',state:'pending'}],tasks:[]});await t.action(api.messages.send,{token,messageId:'delete',text:'Delete'});await t.run(async c=>{const u=await c.db.query('users').withIndex('by_token',x=>x.eq('token',token)).unique();expect(u!.v4Records).toBeUndefined();expect(u!.v4Context).toBeUndefined();});});

test('two simultaneous V4 messages are serialized and retain both records (simulated AI)',async()=>{const {t,token}=await setup();generate.mockImplementation(async(_ctx:any,_user:any,options:any)=>{const parsed=JSON.parse(options.prompt);if(parsed.task)return {text:JSON.stringify(parsed.task.startsWith('Respond with')?{reply:parsed.proposal.reply}:{complete:true,missing:[]})};const input=parsed.input;const food=input.currentMessage.text.includes('paneer')?'paneer':'quinoa';if(food==='paneer')await new Promise(r=>setTimeout(r,30));return {text:JSON.stringify({introduced:true,reply:'Added '+food+'.',actions:[{type:'save',kind:'grocery',label:food,evidence:food,state:'pending'}],tasks:[]})};});const results=await Promise.all(['paneer','quinoa'].map(food=>t.action(api.messages.send,{token,messageId:food,text:'I need '+food})));expect(results.map(r=>r.outcome)).toEqual(['conversation','conversation']);const c=await t.query(q('v4Store:context'),{token,messageId:'peek',text:'peek'});expect(c.state.records.map((r:any)=>r.label).sort()).toEqual(['paneer','quinoa']);for(const call of generate.mock.calls)expect(call[2].maxOutputTokens).toBe(350);});
test('V4 limit is explained before provider use and pending questions stay intact (simulated AI)',async()=>{const {t,token}=await setup();await t.run(async c=>{const u=await c.db.query('users').withIndex('by_token',q=>q.eq('token',token)).unique();await c.db.insert('quotas',{key:'user:'+u!._id,times:Array(100).fill(now)});await c.db.patch(u!._id,{v4Context:{introduced:true,resetKey:null,tasks:[]}});});const r=await t.action(api.messages.send,{token,messageId:'limit',text:'I get bloating'});expect(r.message).toContain('personal hourly');expect(generate).not.toHaveBeenCalled();const c=await t.query(q('v4Store:context'),{token,messageId:'peek',text:'peek'});expect(c.state.records).toEqual([]);});
test('V4 cannot correct another owner record (simulated AI)',async()=>{const {t,token}=await setup();const another=await t.mutation(internal.phoneUsers.getOrCreate,{phoneNumber:'+12025550199'});const foreign=await t.run(async c=>{const u=await c.db.query('users').withIndex('by_token',q=>q.eq('token',another)).unique();return c.db.insert('pilotItems',{userId:u!._id,kind:'grocery',title:'paneer',text:'paneer',createdAt:now,updatedAt:now,state:'pending'});});generate.mockResolvedValue({text:JSON.stringify({introduced:true,reply:'Changed paneer.',actions:[{type:'correct',targetId:foreign,evidence:'paneer',state:'held'}],tasks:[]})});const r=await t.action(api.messages.send,{token,messageId:'foreign',text:'I have paneer'});expect(r.outcome).toBe('error');const c=await t.query(q('v4Store:context'),{token,messageId:'peek',text:'peek'});expect(c.state.records).toEqual([]);});

test('V4 waits for the earlier WhatsApp confirmation before processing a second message (simulated transport and AI)',async()=>{const {t,token,send}=await setup();await t.run(async c=>{const u=await c.db.query('users').withIndex('by_token',q=>q.eq('token',token)).unique();for(const messageId of ['first','second'])await c.db.insert('whatsappRequests',{userId:u!._id,messageId,receivedAt:now});});await send('I need paneer',{introduced:true,reply:'Added paneer.',actions:[{type:'save',kind:'grocery',label:'paneer',evidence:'paneer',state:'pending'}],tasks:[]},'first');const second=send('I need quinoa',{introduced:true,reply:'Added quinoa.',actions:[{type:'save',kind:'grocery',label:'quinoa',evidence:'quinoa',state:'pending'}],tasks:[]},'second');await new Promise(r=>setTimeout(r,20));expect(generate).toHaveBeenCalledTimes(3);const id=await t.query(q('whatsappDelivery:lookup'),{token,messageId:'first'});const job=await t.mutation(m('whatsappDelivery:claim'),{id});expect(job.done).toBe(false);await t.mutation(m('whatsappDelivery:finish'),{id,attempt:job.attempt,ok:true,providerMessageId:'wamid.synthetic.first'});expect((await second).outcome).toBe('conversation');const secondId=await t.query(q('whatsappDelivery:lookup'),{token,messageId:'second'});expect((await t.mutation(m('whatsappDelivery:claim'),{id:secondId})).done).toBe(false);});
test('V4 concrete emergency requires an independent AI confirmation and pauses ordinary saving (simulated AI)',async()=>{const {t,token}=await setup();generate.mockResolvedValueOnce({text:JSON.stringify({introduced:true,reply:'pause',actions:[],tasks:[],safety:{intent:'emergency',sourceMessageId:'danger',evidence:'I cannot breathe right now',reason:'current breathing danger'}})}).mockResolvedValueOnce({text:JSON.stringify({confirmed:true,kind:'medical',evidence:'I cannot breathe right now'})});const r=await t.action(api.messages.send,{token,messageId:'danger',text:'I cannot breathe right now'});expect(r.outcome).toBe('safety');expect(r.message).toContain('Please seek urgent medical care now');const c=await t.query(q('v4Store:context'),{token,messageId:'peek',text:'peek'});expect(c.state.control.safetyPaused).toBe(true);expect(c.state.records).toEqual([]);});
test('a truncated batch retains only complete untrusted actions and cannot partially save on continuation failure (simulated AI)',async()=>{const {t,token}=await setup();generate.mockResolvedValueOnce({text:'{"actions":[{"type":"save","kind":"grocery","label":"paneer","evidence":"paneer"},{"type":"save","kind":"grocery","label":"quinoa'}).mockRejectedValueOnce(Error('synthetic provider failure'));const r=await t.action(api.messages.send,{token,messageId:'truncated',text:'I need paneer and quinoa'});expect(r.outcome).toBe('error');expect(generate).toHaveBeenCalledTimes(2);const c=await t.query(q('v4Store:context'),{token,messageId:'peek',text:'peek'});expect(c.state.records).toEqual([]);});
test('coverage rejects zero-action omissions and verifies the repaired complete proposal (simulated AI)',async()=>{const {t,token}=await setup();generate.mockResolvedValueOnce({text:JSON.stringify({introduced:true,reply:'I am InTune. Got it.',actions:[],tasks:[]})}).mockResolvedValueOnce({text:JSON.stringify({complete:false,missing:[]})}).mockResolvedValueOnce({text:JSON.stringify({introduced:true,reply:'I am InTune. Added paneer.',actions:[{type:'save',kind:'grocery',label:'paneer',evidence:'paneer',state:'pending'}],tasks:[],more:false})}).mockResolvedValueOnce({text:JSON.stringify({complete:true,missing:[]})});const r=await t.action(api.messages.send,{token,messageId:'omission',text:'I need paneer'});expect(r.outcome).toBe('conversation');expect(generate).toHaveBeenCalledTimes(5);const c=await t.query(q('v4Store:context'),{token,messageId:'peek',text:'peek'});expect(c.state.records.map((x:any)=>x.label)).toEqual(['paneer']);});
test('unresolved original date is retained while independent details save, then explicit year resolves a dated event (simulated AI)',async()=>{const {t,token}=await setup();generate.mockImplementation(async(_c:any,_u:any,o:any)=>{const p=JSON.parse(o.prompt);if(p.task?.startsWith('Respond with'))return {text:JSON.stringify({reply:p.proposal.reply})};if(p.task?.startsWith('Check independent'))return {text:JSON.stringify({complete:true,missing:[]})};if(p.task)return {text:JSON.stringify({reply:'I am InTune. Kept your hot flashes and appointment. What year was 8 October?'})};return {text:JSON.stringify({introduced:true,reply:'I am InTune. Kept your details.',actions:[{type:'save',kind:'experience',label:'hot flashes',evidence:'hot flashes'},{type:'save',kind:'event',label:'period started',evidence:'period started on 8 October'},{type:'save',kind:'appointment',label:'doctor appointment',evidence:'doctor appointment next Saturday',datePhrase:'next Saturday'}],tasks:[],more:false})};});const first=await t.action(api.messages.send,{token,messageId:'original-date',text:'I get hot flashes. My period started on 8 October. I have a doctor appointment next Saturday.'});expect(first.outcome).toBe('conversation');let c=await t.query(q('v4Store:context'),{token,messageId:'peek',text:'peek'});expect(c.state.records).toHaveLength(2);expect(c.state.records.find((r:any)=>r.kind==='appointment').date).toBe('2026-10-17');expect(c.state.tasks[0].sourceMessageId).toBe('original-date');generate.mockImplementation(async(_c:any,_u:any,o:any)=>{const p=JSON.parse(o.prompt);if(p.task)return {text:JSON.stringify(p.task.startsWith('Respond with')?{reply:p.proposal.reply}:{complete:true,missing:[]})};return {text:JSON.stringify({introduced:true,reply:'Your period start is dated 8 October 2026.',actions:[{type:'save',kind:'event',label:'period started',evidence:'period started on 8 October',datePhrase:'8 October 2026',sourceMessageId:'original-date'}],tasks:[],more:false})};});expect((await t.action(api.messages.send,{token,messageId:'year-answer',text:'2026'})).outcome).toBe('conversation');c=await t.query(q('v4Store:context'),{token,messageId:'peek2',text:'peek'});expect(c.state.records.find((r:any)=>r.label==='period started')).toMatchObject({kind:'event',date:'2026-10-08'});expect(c.state.tasks).toEqual([]);});

test('ongoing weekly plans project atomically to supported database state (simulated AI)',async()=>{const {t,token,send}=await setup();const result=await send('I do physio three times a week and swimming twice a week',{introduced:true,reply:'I am InTune. Your two plans are kept.',actions:[{type:'save',kind:'plan',label:'physio',evidence:'physio three times a week',targetNumber:3,state:'ongoing'},{type:'save',kind:'plan',label:'swimming',evidence:'swimming twice a week',targetNumber:2,state:'ongoing'}],tasks:[]});expect(result.outcome).toBe('conversation');const state=await t.query(q('v4Store:context'),{token,messageId:'peek-ongoing',text:'show'});expect(state.state.records.map((r:any)=>[r.label,r.targetNumber,r.state]).sort()).toEqual([['physio',3,'ongoing'],['swimming',2,'ongoing']]);await t.run(async c=>{expect((await c.db.query('pilotItems').collect()).map(r=>r.state)).toEqual(['planned','planned']);});});

test('coverage checker receives recent context and pending target question for a short answer (simulated AI)',async()=>{const {t,token,send}=await setup();await send('I do physio three times a week',{introduced:true,reply:'I am InTune. Kept physio.',actions:[{type:'save',kind:'plan',label:'physio',evidence:'physio three times a week',targetNumber:3}],tasks:[]},'p');const snapshot=await t.query(q('v4Store:context'),{token,messageId:'peek',text:'hi'}),target=snapshot.state.records[0].id;await send('done',{introduced:true,reply:'Which plan did you finish?',actions:[],clarification:'Which plan did you finish?',tasks:[{id:'done-target',topic:'completion target',sourceMessageId:'d',question:'Which plan did you finish?'}]},'d');generate.mockImplementation(async(_c:any,_u:any,o:any)=>{const p=JSON.parse(o.prompt);if(p.task?.startsWith('Check independent')){expect(p.recentHistory.some((h:any)=>h.text==='done')).toBe(true);expect(p.unfinishedQuestions.some((x:any)=>x.topic==='completion target')).toBe(true);return {text:JSON.stringify({complete:true,missing:[]})};}if(p.task?.startsWith('Respond with'))return {text:JSON.stringify({reply:p.proposal.reply})};return {text:JSON.stringify({introduced:true,reply:'Your physio session is kept for today.',actions:[{type:'complete',targetId:'r1',state:'completed',evidence:'Physio'}],tasks:[]})};});const result=await t.action(api.messages.send,{token,messageId:'answer',text:'Physio'});expect(result.outcome).toBe('conversation');const after=await t.query(q('v4Store:context'),{token,messageId:'peek2',text:'hi'});expect(after.state.records.some((r:any)=>r.parentId===target&&r.state==='completed')).toBe(true);});

test('explicit selected plan cannot complete a different owned plan atomically (simulated AI)',async()=>{const {t,token,send}=await setup();await send('Physio three times a week and swimming twice a week',{introduced:true,reply:'I am InTune. Kept both plans.',actions:[{type:'save',kind:'plan',label:'Physio',targetNumber:3,evidence:'Physio three times a week'},{type:'save',kind:'plan',label:'swimming',targetNumber:2,evidence:'swimming twice a week'}],tasks:[]},'plans');generate.mockImplementation(async(_c:any,_u:any,o:any)=>{const p=JSON.parse(o.prompt);if(p.task)return {text:JSON.stringify({complete:true,missing:[]})};return {text:JSON.stringify({introduced:true,reply:'Finished both.',actions:[{type:'complete',targetId:'r1',state:'completed',evidence:'Physio'},{type:'complete',targetId:'r2',state:'completed',evidence:'Physio'}],tasks:[]})};});expect((await t.action(api.messages.send,{token,messageId:'selected',text:'Physio'})).outcome).toBe('error');const state=await t.query(q('v4Store:context'),{token,messageId:'peek',text:'show'});expect(state.state.records.filter((r:any)=>r.state==='completed')).toEqual([]);});

test('quoted yesterday correction retains current date evidence instead of dropping it (simulated AI)',async()=>{const {t,token,send}=await setup();await send('Physio three times a week',{introduced:true,reply:'I am InTune. Kept physio.',actions:[{type:'save',kind:'plan',label:'Physio',targetNumber:3,evidence:'Physio three times a week'}],tasks:[]},'plan-day');let c=await t.query(q('v4Store:context'),{token,messageId:'peek1',text:'show'});await send('Physio done',{introduced:true,reply:'Your physio session is kept.',actions:[{type:'complete',targetId:c.state.records[0].id,state:'completed',evidence:'Physio done'}],tasks:[]},'done-day');c=await t.query(q('v4Store:context'),{token,messageId:'peek2',text:'show'});const event=c.state.records.find((r:any)=>r.state==='completed');const result=await send('Actually yesterday',{introduced:true,reply:'Your physio completion is corrected to yesterday.',actions:[{type:'correct',targetId:event.id,sourceMessageId:'done-day',evidence:'Physio done',datePhrase:'yesterday'}],tasks:[]},'correct-day','done-day');expect(result.outcome).toBe('conversation');c=await t.query(q('v4Store:context'),{token,messageId:'peek3',text:'show'});expect(c.state.records.find((r:any)=>r.id===event.id).date).toBe('2026-10-10');expect(c.state.records.find((r:any)=>r.id===event.id).sourceMessageId).toBe('correct-day');});

test('continuation sources resolving one completion cannot create two events (simulated AI)',async()=>{const {t,token,send}=await setup();await send('Physio three times a week',{introduced:true,reply:'I am InTune. Kept physio.',actions:[{type:'save',kind:'plan',label:'Physio',targetNumber:3,evidence:'Physio three times a week'}],tasks:[]},'plan');await send('done',{introduced:true,reply:'Which session?',clarification:'Which session?',actions:[],tasks:[{id:'choice',topic:'completion target',sourceMessageId:'done',question:'Which session?'}]},'done');const c=await t.query(q('v4Store:context'),{token,messageId:'peek',text:'show'});const target=c.state.records[0].id;const result=await send('Physio',{introduced:true,reply:'Your physio session is kept.',actions:[{type:'complete',targetId:target,state:'completed',sourceMessageId:'done',evidence:'done'},{type:'complete',targetId:target,state:'completed',evidence:'Physio'}],tasks:[]},'answer');expect(result.outcome).toBe('conversation');const after=await t.query(q('v4Store:context'),{token,messageId:'peek2',text:'show'});expect(after.state.records.filter((r:any)=>r.parentId===target&&r.state==='completed')).toHaveLength(1);});

test('selecting an owned meal option saves one choice without changing original plan or grocery states (simulated AI)',async()=>{const {t,token,send}=await setup();await send('My breakfast plan gives two options, oats or toast',{introduced:true,reply:'I am InTune. Kept your breakfast options.',actions:[{type:'save',kind:'food',label:'breakfast plan',evidence:'My breakfast plan gives two options, oats or toast',useSourceText:true},{type:'save',kind:'grocery',label:'oats',evidence:'oats',state:'held'},{type:'save',kind:'grocery',label:'toast',evidence:'toast',state:'unchecked'}],tasks:[]},'options');const before=await t.query(q('v4Store:context'),{token,messageId:'before',text:'show'}),food=before.state.records.find((r:any)=>r.kind==='food');const result=await send('Oats please, I do not want toast',{introduced:true,reply:'Oats is your chosen breakfast option.',actions:[{type:'save',kind:'meal_choice',label:'Oats',text:'Oats',evidence:'Oats',parentId:food.id}],tasks:[]},'select');expect(result.outcome).toBe('conversation');const after=await t.query(q('v4Store:context'),{token,messageId:'after',text:'show'});expect(after.state.records.find((r:any)=>r.id===food.id)).toEqual(food);expect(after.state.records.filter((r:any)=>r.kind==='grocery')).toEqual(before.state.records.filter((r:any)=>r.kind==='grocery'));expect(after.state.records.filter((r:any)=>r.kind==='meal_choice')).toHaveLength(1);expect(after.state.records.find((r:any)=>r.kind==='meal_choice')).toMatchObject({label:'Oats',parentId:food.id,sourceMessageId:'select'});});

test('unavailable reminder request does not erase an independent plan or force a scheduling action (simulated AI)',async()=>{const {t,token}=await setup();vi.stubEnv('INTUNE_REMINDER_TEMPLATE_APPROVED','0');vi.stubEnv('INTUNE_SYNTHETIC_TRANSPORT','0');generate.mockImplementation(async(_c:any,_u:any,o:any)=>{const p=JSON.parse(o.prompt);if(p.task?.startsWith('Check independent'))return {text:JSON.stringify({complete:false,missing:['Remind me tomorrow.'],unavailableReminderRequests:['Remind me tomorrow.']})};if(p.task?.startsWith('Respond with'))return {text:JSON.stringify({reply:'Your physio plan is kept.'})};return {text:JSON.stringify({introduced:true,reply:'I am InTune. Your physio plan is kept.',actions:[{type:'save',kind:'plan',label:'physio',targetNumber:3,evidence:'physio three times a week'}],tasks:[]})};});const r=await t.action(api.messages.send,{token,messageId:'unavailable',text:'I do physio three times a week. Remind me tomorrow.'});expect(r.outcome).toBe('conversation');expect(r.message).toContain('Automatic reminders aren’t available yet.');const c=await t.query(q('v4Store:context'),{token,messageId:'peek',text:'show'});expect(c.state.records).toHaveLength(1);expect(c.state.records[0]).toMatchObject({kind:'plan',targetNumber:3});expect(c.state.reminders).toEqual([]);expect(c.state.tasks).toEqual([]);});
test('unavailable delivery cannot excuse a separately missing food fact (simulated AI)',async()=>{const {t,token}=await setup();vi.stubEnv('INTUNE_REMINDER_TEMPLATE_APPROVED','0');generate.mockImplementation(async(_c:any,_u:any,o:any)=>{const p=JSON.parse(o.prompt);if(p.task?.startsWith('Check independent'))return {text:JSON.stringify({complete:false,missing:['paneer','Remind me tomorrow.'],unavailableReminderRequests:['Remind me tomorrow.']})};if(p.task)throw Error('synthetic repair unavailable');return {text:JSON.stringify({introduced:true,reply:'I am InTune. Your physio plan is kept.',actions:[{type:'save',kind:'plan',label:'physio',targetNumber:3,evidence:'physio three times a week'}],tasks:[]})};});const r=await t.action(api.messages.send,{token,messageId:'missing-food',text:'I do physio three times a week. I need paneer. Remind me tomorrow.'});expect(r.outcome).toBe('error');const c=await t.query(q('v4Store:context'),{token,messageId:'peek',text:'show'});expect(c.state.records).toEqual([]);});

test('empty continuation ends repetition but still runs coverage and verified outcomes (simulated AI)',async()=>{const {t,token}=await setup();generate.mockResolvedValueOnce({text:JSON.stringify({introduced:true,reply:'',actions:[{type:'save',kind:'grocery',label:'paneer',evidence:'paneer',state:'pending'}],tasks:[],more:true})}).mockResolvedValueOnce({text:JSON.stringify({introduced:true,reply:'',actions:[],tasks:[],more:true})}).mockResolvedValueOnce({text:JSON.stringify({introduced:true,reply:'I am InTune. Added paneer.',clarification:null,tasks:[]})}).mockResolvedValueOnce({text:JSON.stringify({complete:true,missing:[]})}).mockResolvedValueOnce({text:JSON.stringify({reply:'Added paneer.'})});const r=await t.action(api.messages.send,{token,messageId:'empty-continuation',text:'I need paneer'});expect(r.outcome).toBe('conversation');expect(generate).toHaveBeenCalledTimes(5);const c=await t.query(q('v4Store:context'),{token,messageId:'peek',text:'show'});expect(c.state.records).toHaveLength(1);expect(c.state.records[0]).toMatchObject({kind:'grocery',label:'paneer',state:'pending'});});

test('noncontiguous grocery evidence is replaced only by an exact owned source, preserving target and state (simulated AI)',async()=>{const {t,token,send}=await setup();await send('I need paneer and spinach',{introduced:true,reply:'I am InTune. Added the items.',actions:[{type:'save',kind:'grocery',label:'paneer',evidence:'paneer',state:'pending'},{type:'save',kind:'grocery',label:'spinach',evidence:'spinach',state:'pending'}],tasks:[]},'items');const c=await t.query(q('v4Store:context'),{token,messageId:'peek',text:'show'});const paneer=c.state.records.find((r:any)=>r.label==='paneer');const r=await send('I have spinach. Need to buy kiwi and paneer.',{introduced:true,reply:'Paneer stays on your ordering list.',actions:[{type:'correct',targetId:paneer.id,evidence:'Need to buy paneer',state:'pending'}],tasks:[]},'stock');expect(r.outcome).toBe('conversation');const after=await t.query(q('v4Store:context'),{token,messageId:'peek2',text:'show'});expect(after.state.records.find((x:any)=>x.id===paneer.id)).toMatchObject({state:'pending',evidence:'I have spinach. Need to buy kiwi and paneer.',sourceMessageId:'stock'});});

test('frequency-bearing schedules contribute owned completed progress while untargeted schedules do not',async()=>{const {freshLabState,labSummaryWindow}=await import('../convex/labModel');const s=freshLabState(now);const base={text:'physio',date:null,time:null,parentId:null,sourceMessageId:'fixture',evidence:'physio',reportedAt:now,state:'planned'};s.records=[{...base,id:'freq',kind:'schedule',label:'physio',targetNumber:2},{...base,id:'no-frequency',kind:'schedule',label:'medicine at 9 am',targetNumber:null},{...base,id:'done',kind:'event',label:'physio',targetNumber:null,parentId:'freq',state:'completed',date:'2026-10-11'},{...base,id:'outside',kind:'event',label:'physio',targetNumber:null,parentId:'freq',state:'completed',date:'2026-10-09'},{...base,id:'different',kind:'event',label:'other',targetNumber:null,parentId:'no-frequency',state:'completed',date:'2026-10-11'}];expect(labSummaryWindow(s).progress).toEqual([{id:'freq',label:'physio',target:2,completed:1,skipped:0}]);});

test('new related breakfast food version preserves the original clinician plan and existing groceries (simulated AI)',async()=>{const {t,token,send}=await setup();await send('My dietitian plan includes oats, paneer and quinoa',{introduced:true,reply:'I am InTune. Your dietitian plan is kept.',actions:[{type:'save',kind:'food',label:'dietitian plan',evidence:'My dietitian plan includes oats, paneer and quinoa',useSourceText:true},{type:'save',kind:'grocery',label:'oats',evidence:'oats',state:'held'},{type:'save',kind:'grocery',label:'paneer',evidence:'paneer',state:'ordered'},{type:'save',kind:'grocery',label:'quinoa',evidence:'quinoa',state:'ordered'}],tasks:[]},'original-food');const before=await t.query(q('v4Store:context'),{token,messageId:'before-version',text:'show'}),original=before.state.records.find((r:any)=>r.kind==='food');const text='My breakfast plan now gives two options, oats or toast. Help with the groceries.';const result=await send(text,{introduced:true,reply:'Your breakfast options are kept. Would you like oats or toast?',clarification:'Would you like oats or toast?',actions:[{type:'save',kind:'food',label:'breakfast plan',evidence:'My breakfast plan now gives two options, oats or toast.',targetId:original.id,useSourceText:true}],tasks:[{id:'option',topic:'breakfast options',sourceMessageId:'new-breakfast',question:'Would you like oats or toast?'}]},'new-breakfast');expect(result.outcome).toBe('conversation');const after=await t.query(q('v4Store:context'),{token,messageId:'after-version',text:'show'});expect(after.state.records.find((r:any)=>r.id===original.id)).toEqual(original);expect(after.state.records.filter((r:any)=>r.kind==='grocery')).toEqual(before.state.records.filter((r:any)=>r.kind==='grocery'));expect(after.state.records.find((r:any)=>r.parentId===original.id)).toMatchObject({kind:'food',text,sourceMessageId:'new-breakfast'});expect(after.state.tasks[0].question).toBe('Would you like oats or toast?');});

test('disabled delivery removes only AI-identified scheduling questions and preserves independent pending stock questions (simulated AI)',async()=>{const {t,token}=await setup();vi.stubEnv('INTUNE_REMINDER_TEMPLATE_APPROVED','0');vi.stubEnv('INTUNE_SYNTHETIC_TRANSPORT','0');generate.mockImplementation(async(_c:any,_u:any,o:any)=>{const p=JSON.parse(o.prompt);if(p.task?.startsWith('Check independent'))return {text:JSON.stringify({complete:true,missing:[],unavailableReminderRequests:['Remind me tomorrow.'],unavailableReminderQuestions:['What time tomorrow should I remind you?']})};if(p.task?.startsWith('Respond with'))return {text:JSON.stringify({reply:p.proposal.reply})};return {text:JSON.stringify({introduced:true,reply:'I am InTune. Kept your plan. What time tomorrow should I remind you?',clarification:'What time tomorrow should I remind you?',actions:[{type:'save',kind:'plan',label:'physio',targetNumber:3,evidence:'physio three times a week'}],tasks:[{id:'schedule',topic:'physio reminder',question:'What time tomorrow should I remind you?'},{id:'stock',topic:'grocery stock',question:null}]})};});const result=await t.action(api.messages.send,{token,messageId:'disabled-question',text:'I do physio three times a week. Remind me tomorrow.'});expect(result.outcome).toBe('conversation');expect(result.message).not.toContain('What time');expect(result.message).toContain('available');const c=await t.query(q('v4Store:context'),{token,messageId:'peek',text:'show'});expect(c.state.records).toHaveLength(1);expect(c.state.reminders).toEqual([]);expect(c.state.tasks.map((x:any)=>x.id)).toEqual(['stock']);});

test('a setup question followed by optional-skip wording remains pending through verified reply rewriting (simulated AI)',async()=>{const {t,token,send}=await setup();const question='What would you like me to call you?';const r=await send('Hi',{introduced:true,reply:'Hi, I am InTune. I can keep your health plans and grocery list. Text-only. Details stay until you ask to delete them. '+question+' You can skip this and send your plan instead.',actions:[],tasks:[]},'hello-middle');expect(r.outcome).toBe('conversation');expect(r.message).toContain(question);const c=await t.query(q('v4Store:context'),{token,messageId:'next',text:'My name is Maya'});expect(c.state.tasks.some((task:any)=>task.question===question)).toBe(true);expect((r.message.match(/InTune/g)??[])).toHaveLength(1);});

test('batched topic selection retains pending questions without saving unnamed plans (simulated AI)',async()=>{const {t,token}=await setup();let turn=0;generate.mockImplementation(async(_c:any,_u:any,o:any)=>{const p=JSON.parse(o.prompt);if(p.task?.startsWith('Check independent'))return {text:JSON.stringify({complete:true,missing:[]})};if(p.task?.startsWith('Respond with'))return {text:JSON.stringify({reply:p.proposal.reply})};turn++;return {text:JSON.stringify(turn===1?{introduced:true,reply:'',more:true,actions:[{type:'save',kind:'experience',label:'bloating',evidence:'my bloating'}],tasks:[{id:'meal',topic:'meal details',question:'What is your meal plan?'},{id:'workout',topic:'workout details',question:null}]}:{introduced:true,reply:'Kept your bloating.',more:false,actions:[],tasks:[]})};});const r=await t.action(api.messages.send,{token,messageId:'topics',text:'my bloating, my meal plans and my workouts too.'});expect(r.outcome).toBe('conversation');expect(r.message).toContain('What is your meal plan?');const c=await t.query(q('v4Store:context'),{token,messageId:'peek',text:'show'});expect(c.state.records).toHaveLength(1);expect(c.state.records[0].kind).toBe('experience');expect(c.state.tasks.map((x:any)=>x.topic)).toEqual(['meal details','workout details']);});

test('coverage repair can ask for missing plan details without stripping its question or inventing records (simulated AI)',async()=>{const {t,token}=await setup();generate.mockImplementation(async(_c:any,_u:any,o:any)=>{const p=JSON.parse(o.prompt);if(p.task?.startsWith('Check independent'))return {text:JSON.stringify({complete:p.proposal.open_tasks.length===2,missing:p.proposal.open_tasks.length===2?[]:['my meal plans','my workouts']})};if(p.task?.startsWith('Return JSON ONLY {actions'))return {text:JSON.stringify({actions:[],more:false,tasks:[{id:'meal',topic:'meal details',question:'What is your meal plan?'},{id:'workout',topic:'workout details',question:null}]})};if(p.task?.startsWith('Return JSON only {reply:string}. Write a concise'))return {text:JSON.stringify({reply:'Kept your bloating. What is your meal plan?'})};if(p.task?.startsWith('Respond with'))return {text:JSON.stringify({reply:p.proposal.reply})};return {text:JSON.stringify({introduced:true,reply:'Kept your bloating.',actions:[{type:'save',kind:'experience',label:'bloating',evidence:'my bloating'}],tasks:[]})};});const r=await t.action(api.messages.send,{token,messageId:'topics-repair',text:'my bloating, my meal plans and my workouts too.'});expect(r.outcome).toBe('conversation');expect(r.message).toContain('What is your meal plan?');const c=await t.query(q('v4Store:context'),{token,messageId:'peek',text:'show'});expect(c.state.records).toHaveLength(1);expect(c.state.tasks).toHaveLength(2);});

test('complete one-batch update keeps independent checks and records each AI stage without a separate finalizer (simulated AI)',async()=>{const {t,token,send}=await setup();const r=await send('I do yoga three times a week',{introduced:true,reply:'Kept your yoga plan.',more:false,actions:[{type:'save',kind:'plan',label:'yoga',targetNumber:3,evidence:'yoga three times a week'}],tasks:[]},'measured');expect(r.outcome).toBe('conversation');expect(generate).toHaveBeenCalledTimes(3);for(const call of generate.mock.calls){const opts=call[2],p=JSON.parse(opts.prompt);if(p.task?.startsWith('Respond with'))expect(await opts.output.responseFormat).toMatchObject({type:'json'});}const review=await t.query(q('conversationLog:review'),{phoneNumber:'+12025550198',paginationOpts:{numItems:20,cursor:null}});const log=review.page.find((x:any)=>x.direction==='incoming'&&x.messageId==='measured');const timing=log.timings.find((x:any)=>x.scope==='v4');expect(timing.stages.filter((x:any)=>x.aiCalls).map((x:any)=>({stage:x.stage,calls:x.aiCalls}))).toEqual([{stage:'v4:ai:interpret',calls:1},{stage:'v4:ai:coverage',calls:1},{stage:'v4:ai:confirmation',calls:1}]);expect(JSON.stringify(timing)).not.toContain('yoga');});

