test('first contact during safety pause asks the approved return question and never saves the paused report (simulated AI)',async()=>{const {t,token,send}=await setup();await t.run(async c=>{const u=await c.db.query('users').withIndex('by_token',x=>x.eq('token',token)).unique();await c.db.patch(u!._id,{safetyKind:'medical',safetyReturnAsked:false});});const r=await send('I had bloating too',{introduced:true,reply:'I cannot save that now.',actions:[],tasks:[]},'paused-followup');expect(r.message).toContain('Are you okay to continue with normal tracking now?');const c=await t.query(q('v4Store:context'),{token,messageId:'peek',text:''});expect(c.state.control.safetyAsked).toBe(true);expect(c.state.control.safetyPaused).toBe(true);expect(c.state.records).toEqual([]);});

for(const confirmed of [true,false])test('malformed affirmative safety evidence receives one bounded recheck; confirmed='+confirmed+' (simulated AI)',async()=>{const {t,token}=await setup();await t.run(async c=>{const u=await c.db.query('users').withIndex('by_token',x=>x.eq('token',token)).unique();await c.db.patch(u!._id,{safetyKind:'medical',safetyReturnAsked:true});});let checks=0;generate.mockImplementation(async(_c:any,_u:any,o:any)=>{const p=JSON.parse(o.prompt);if(p.task?.startsWith('Independently')){expect(p.question).toBe('Are you okay to continue with normal tracking now?');return {text:JSON.stringify(++checks===1?{confirmed:true,evidence:'This is an affirmative answer.'}:{confirmed,evidence:'Yes, I can continue normal tracking now'})};}return {text:JSON.stringify({introduced:true,reply:'Thanks, we can continue.',actions:[],tasks:[],safety:{intent:'return',sourceMessageId:'resume-evidence',evidence:'Yes, I can continue normal tracking now',reason:'Affirmative'}})};});const r=await t.action(api.messages.send,{token,messageId:'resume-evidence',text:'Yes, I can continue normal tracking now'});expect(checks).toBe(2);expect(generate).toHaveBeenCalledTimes(3);expect(r.outcome).toBe(confirmed?'safety_resumed':'error');const c=await t.query(q('v4Store:context'),{token,messageId:'peek',text:''});expect(c.state.control.safetyPaused).toBe(!confirmed);expect(c.state.records).toEqual([]);});

