test('available reminder overrides stale unavailable history and persists relative one-off purpose atomically (simulated AI)',async()=>{const {t,token}=await setup();vi.stubEnv('WHATSAPP_ACCESS_TOKEN','fictional');vi.stubEnv('WHATSAPP_PHONE_NUMBER_ID','123');vi.stubEnv('INTUNE_REMINDER_TEMPLATE_APPROVED','1');vi.stubEnv('INTUNE_REMINDER_TEMPLATE','intune_requested_reminder_v1');let proposals=0;generate.mockImplementation(async(_c:any,_u:any,o:any)=>{const p=JSON.parse(o.prompt);if(p.task?.startsWith('Check independent'))return {text:JSON.stringify(p.proposal.actions.length?{complete:true,missing:[],availableReminderRequestUnresolved:false}:{complete:true,missing:[],availableReminderRequestUnresolved:true})};if(p.task?.startsWith('Respond with'))return {text:JSON.stringify({reply:'Your workout reminder is set for five minutes from your message.'})};if(++proposals===1)return {text:JSON.stringify({introduced:true,reply:'I cannot send reminders.',actions:[],tasks:[]})};return {text:JSON.stringify({introduced:true,reply:'Your workout reminder is set.',actions:[{type:'save',kind:'task',label:'workout',evidence:'workout',tempId:'purpose'},{type:'reminder',targetId:'purpose',evidence:'Remind me in 5 minutes for a workout',permissionEvidence:'Remind me in 5 minutes for a workout',timePhrase:'in 5 minutes',repeat:'once',tempId:'rem'}],tasks:[]})};});const reply=await t.action(api.messages.send,{token,messageId:'relative-reminder',text:'Remind me in 5 minutes for a workout'});expect(reply.outcome).toBe('conversation');expect(reply.message).toContain('reminder is set');const context=await t.query(q('v4Store:context'),{token,messageId:'peek',text:''});expect(context.state.records).toHaveLength(1);expect(context.state.reminders).toHaveLength(1);expect(context.state.reminders[0].dueAt).toBe(now+300000);expect(proposals).toBe(2);await t.action(api.messages.send,{token,messageId:'pause-relative',text:'Pause'});const paused=await t.query(q('v4Store:context'),{token,messageId:'peek-paused',text:''});expect(paused.state.control.tracking).toBe('paused');expect(paused.state.reminders[0].state).toBe('suppressed');vi.mocked(Date.now).mockReturnValue(now+300000);expect(await t.mutation(m('pilotReminders:claim'),{id:context.state.reminders[0].id,dueAt:now+300000})).toBeNull();});

test.each([true,false])('contextual reminder needs independent current permission confirmation: %s (simulated AI)',async confirmed=>{const {t,token,send}=await setup();vi.stubEnv('WHATSAPP_ACCESS_TOKEN','fictional');vi.stubEnv('WHATSAPP_PHONE_NUMBER_ID','123');vi.stubEnv('INTUNE_REMINDER_TEMPLATE_APPROVED','1');vi.stubEnv('INTUNE_REMINDER_TEMPLATE','intune_requested_reminder_v1');const original='Please remind me to walk in 5 minutes';await send(original,{introduced:true,reply:'Your walk reminder is set.',actions:[{type:'save',kind:'task',label:'walk',evidence:'walk',tempId:'purpose'},{type:'reminder',targetId:'purpose',timePhrase:'in 5 minutes',permissionEvidence:original,evidence:original,repeat:'once'}],tasks:[]});let c=await t.query(q('v4Store:context'),{token,messageId:'peek',text:''});const target=c.state.records[0].id;await t.run(async ctx=>{await ctx.db.patch(c.state.reminders[0].id,{state:'stopped'});});vi.mocked(Date.now).mockReturnValue(now+600000);const current='Ok walk in 5 minutes';const action={type:'reminder',targetId:target,timePhrase:'5 minutes',permissionEvidence:original,evidence:'walk in 5 minutes',repeat:'once'};generate.mockImplementation(async(_ctx:any,_u:any,o:any)=>{const p=JSON.parse(o.prompt);if(p.task?.startsWith('Check independent'))return {text:JSON.stringify({complete:true,missing:[],contextualReminderPermissions:confirmed?[{actionIndex:0,evidence:current}]:[]})};if(p.task?.startsWith('Respond with')||p.task?.startsWith('Return JSON only {reply:string}'))return {text:JSON.stringify({reply:'Your new walk reminder is set.'})};return {text:JSON.stringify({introduced:true,reply:'Your walk reminder is set.',actions:[action],tasks:[],more:false})};});const reply=await t.action(api.messages.send,{token,messageId:'contextual',text:current});c=await t.query(q('v4Store:context'),{token,messageId:'peek-next',text:''});if(confirmed){expect(reply.outcome).toBe('conversation');expect(c.state.reminders).toHaveLength(2);expect(c.state.reminders.at(-1).permission).toBe(current);}else{expect(reply.outcome).toBe('error');expect(c.state.reminders).toHaveLength(1);}});

