test.each(['correction','unclear'])('a portion follow-up uses an independently checked meal relationship: %s (simulated AI)',async relation=>{
 const {t,token,send}=await setup();const eaten='Yesterday I ate 3 idlis and sambar rice';await send(eaten,{introduced:true,reply:'Kept your reported meal.',actions:[{type:'save',kind:'event',label:'3 idlis and sambar rice',text:eaten,evidence:eaten,datePhrase:'Yesterday',state:'completed'}],tasks:[]},'previous-meal');
 generate.mockImplementation(async(_c:any,_u:any,o:any)=>{const p=JSON.parse(o.prompt);if(p.task?.startsWith('Classify a food intake'))return {text:JSON.stringify({relation,evidence:p.currentMessage.text})};if(p.task?.startsWith('Check independent'))return {text:JSON.stringify({complete:true,missing:[],replyVerified:false})};if(p.task)return {text:JSON.stringify({reply:p.proposal?.reply??'Checked your meal.'})};throw Error('Unexpected interpretation');});
 const text='3 idlis, 2 bowls of rice and 1 bowl of sambar';const r=await send(text,{introduced:true,reply:'Kept your meal quantities.',actions:[{type:'save',kind:'event',label:text,text,evidence:text,datePhrase:'today'}],tasks:[]},'portion-answer');expect(r.outcome).toBe('conversation');const state=(await t.query(q('v4Store:context'),{token,messageId:'peek-portions',text:''})).state;const events=state.records.filter((x:any)=>x.kind==='event');expect(events).toHaveLength(1);expect(events[0].date).toBe('2026-10-10');if(relation==='correction'){expect(events[0].text).toBe(text);expect(events[0].state).toBe('completed');}else{expect(events[0].text).toBe(eaten);expect(r.message).toContain('correction to that meal');}
});


test('today physio skip persists once and weekly retrieval counts it separately while preserving all scheduled reminders (simulated AI)',async()=>{
 const {t,token,send}=await setup();await send('I go to physio three times a week',{introduced:true,reply:'Your physio plan is kept.',actions:[{type:'save',kind:'plan',label:'physio',targetNumber:3,evidence:'physio three times a week'}],tasks:[]},'plan-skip');
 const before=await t.query(q('v4Store:context'),{token,messageId:'peek-skip',text:'show'}),plan=before.state.records[0];
 await t.run(async c=>{const u=(await c.db.query('users').withIndex('by_token',q=>q.eq('token',token)).unique())!;for(const offset of [1,3,5])await c.db.insert('pilotReminders',{userId:u._id,itemId:plan.id,kind:'tracking',title:'physio',permissionText:'Remind me about physio at 8:30 am every Monday Wednesday and Friday',timezone:'Asia/Kolkata',localTime:'08:30',dueAt:now+offset*86400000,repeat:'weekly',state:'active',createdAt:now});});
 const jobs=(await t.query(q('v4Store:context'),{token,messageId:'before-skip',text:'show'})).state.reminders;
 for(const [id,text]of [['skip-first','I dont want to do physio today'],['skip-again','skip physio today']]){const result=await send(text,{introduced:true,reply:id==='skip-first'?'One physio session is recorded as skipped today.':'That session is already recorded as skipped.',actions:[{type:'complete',targetId:plan.id,state:'skipped',datePhrase:'today',evidence:text}],tasks:[]},id);expect(result.outcome).toBe('conversation');}
 const after=await t.query(q('v4Store:context'),{token,messageId:'after-skip',text:'show'});expect(after.state.reminders).toEqual(jobs);expect(after.state.records.filter((r:any)=>r.state==='skipped')).toHaveLength(1);expect(after.state.records.filter((r:any)=>r.state==='completed')).toHaveLength(0);expect(after.state.records.find((r:any)=>r.id===plan.id)).toEqual(plan);
 const summary=await t.query(q('conversationStore:recordReply'),{token,scope:'week'});expect(summary.message).toContain('1 reported skipped');expect(summary.message).toContain('0/3');
});

